package common.model;

/**
 * Stores the result of a recovery analysis.
 *
 * This model contains statistics generated by the RecoveryEngine
 * after analysing a range of sectors.
 */
public class RecoveryResult {

    private final long startSector;
    private final long totalScanned;
    private final long recoverableSectors;
    private final long emptySectors;

    /**
     * Creates a new RecoveryResult.
     *
     * @param startSector        first sector analysed
     * @param totalScanned       total number of sectors analysed
     * @param recoverableSectors sectors containing recoverable data
     * @param emptySectors       sectors containing no recoverable data
     */
    public RecoveryResult(
            long startSector,
            long totalScanned,
            long recoverableSectors,
            long emptySectors) {

        if (startSector < 0) {
            throw new IllegalArgumentException(
                    "Start sector cannot be negative");
        }

        if (totalScanned < 0) {
            throw new IllegalArgumentException(
                    "Total scanned sectors cannot be negative");
        }

        if (recoverableSectors < 0) {
            throw new IllegalArgumentException(
                    "Recoverable sectors cannot be negative");
        }

        if (emptySectors < 0) {
            throw new IllegalArgumentException(
                    "Empty sectors cannot be negative");
        }

        if (recoverableSectors + emptySectors != totalScanned) {
            throw new IllegalArgumentException(
                    "Recoverable and empty sectors must equal total scanned sectors");
        }

        this.startSector = startSector;
        this.totalScanned = totalScanned;
        this.recoverableSectors = recoverableSectors;
        this.emptySectors = emptySectors;
    }

    public long getStartSector() {
        return startSector;
    }

    public long getTotalScanned() {
        return totalScanned;
    }

    public long getRecoverableSectors() {
        return recoverableSectors;
    }

    public long getEmptySectors() {
        return emptySectors;
    }

    /**
     * Returns true if at least one sector contains recoverable data.
     */
    public boolean hasRecoverableData() {
        return recoverableSectors > 0;
    }

    /**
     * Calculates the percentage of scanned sectors
     * that contain recoverable data.
     */
    public double getRecoveryPercentage() {

        if (totalScanned == 0) {
            return 0.0;
        }

        return ((double) recoverableSectors / totalScanned) * 100.0;
    }

    @Override
    public String toString() {
        return "RecoveryResult{" +
                "startSector=" + startSector +
                ", totalScanned=" + totalScanned +
                ", recoverableSectors=" + recoverableSectors +
                ", emptySectors=" + emptySectors +
                '}';
    }
}
